# 세응(世應) 위치 패턴 — 정통 팔궁괘서 규칙: 세효 = 6·1·2·3·4·5·4·3(游魂은 4세와
# 같은 자리, 歸魂은 3세와 같은 자리), 응효 = 세효에서 3자리 건너(세+3, 6 넘으면 -6).
_SEEUNG_PATTERN = [(6, 3), (1, 4), (2, 5), (3, 6), (4, 1), (5, 2), (4, 1), (3, 6)]

GUA_GUNG = {}   # 64괘명 → 소속 궁(宮)의 대표 팔괘(乾坎艮震巽離坤兌 중 하나)
SEEUNG = {}     # 64괘명 → (세효 위치, 응효 위치), 1=초효 ~ 6=상효
for _gung, _names in _GUNG_GROUPS.items():
    for _name, _pos in zip(_names, _SEEUNG_PATTERN):
        GUA_GUNG[_name] = _gung
        SEEUNG[_name] = _pos

assert len(GUA_GUNG) == 64 and len(SEEUNG) == 64, "GUA_GUNG·SEEUNG도 64괘 전수여야 한다"
# _GUNG_GROUPS를 손으로 옮겨 적었으므로, GUA_64의 실제 64개 이름과 정확히
# 일치하는지(오탈자 없는지) 여기서 교차검증한다.
assert set(GUA_GUNG) == set(GUA_64.values()), "GUA_GUNG 괘명이 GUA_64와 불일치"

# ── HYO_TEXT(효사) 전수 검증 — 8궁 384효(64괘×6효) 완료(4-B) ─────
assert len(HYO_TEXT) == 64, "HYO_TEXT는 64괘 전수여야 한다"
assert set(HYO_TEXT) == set(GUA_64.values()), "HYO_TEXT 괘명이 GUA_64와 불일치(오배치 있음)"
assert all(len(_v) == 6 for _v in HYO_TEXT.values()), "효사가 6개가 아닌 괘가 있다"
assert sum(len(_v) for _v in HYO_TEXT.values()) == 384, "효사 총합이 384개(64괘×6효)가 아니다"


