        "쉽게 말하면: 정성을 다해 예의를 갖추는 시기예요. 그렇게 하면 좋은 결과가 있습니다.",
        "쉽게 말하면: 계단을 오르듯 한 걸음씩 차근차근 나아가는 시기예요. 바른 태도를 지키면 좋습니다.",
