        "쉽게 말하면: 손발이 안 맞아 협력이 어긋나면서 가까운 사이에도 갈등이 생기는 시기예요.",
        "쉽게 말하면: 진심을 다하면 위험과 걱정이 걷히는 시기예요. 문제 될 게 없습니다.",
