        "쉽게 말하면: 바깥일보다 집안일이나 내부 관리를 더 정성껏 챙겨야 하는 시기예요. 바르게 지키면 좋습니다.",
        "쉽게 말하면: 다소 엄격하게 단속하느라 힘들고 부담스러운 시기지만, 결국은 좋은 결과로 이어져요. 오히려 너무 느슨하게 넘기면 나중에 부끄러운 일이 생깁니다.",
